// caveman-shrink — pure-Node prose compressor for MCP tool descriptions
// and other safe string fields. Mirrors the boundaries of the
// caveman-compress Python tool (preserve code, URLs, paths, identifiers)
// but reimplemented in Node so the proxy stays single-runtime.
//
// API: compress(text, opts?) → { compressed, before, after }
//
// Boundaries (NEVER touched):
//  - fenced code blocks (``` ... ```)
//  - inline code (`...`)
//  - URLs (https?://...)
//  - filesystem paths (anything with `/` or `\`)
//  - "code-looking" tokens (parens at end, semicolons, JSON-like braces)
//  - identifiers in CamelCase / snake_case / dotted.path form
//
// Compression applied to everything else:
//  - drop articles (a, an, the)
//  - drop filler words (just, really, basically, actually, simply, quite, very)
//  - drop pleasantries (please, kindly, thank you, sure, certainly)
//  - drop hedging (perhaps, maybe, might, could potentially, would like to)
//  - drop leading "I'll" / "I will" / "you can" / "we will" / "let me"
//  - collapse whitespace runs

const FILLERS = new RegExp(
  '\\b(?:just|really|basically|actually|simply|quite|very|essentially|literally)\\b',
  'gi'
);

const PLEASANTRIES = new RegExp(
  '\\b(?:please|kindly|thank you|thanks|sure|certainly|of course|happy to|i\'?d be happy)\\b[,.]?\\s*',
  'gi'
);

const HEDGES = new RegExp(
  '\\b(?:perhaps|maybe|might|could potentially|would like to|i think|in my opinion|it seems|it appears)\\b\\s*',
  'gi'
);

const LEADERS = new RegExp(
  '^(?:i\'?ll|i will|i can|i\'?d|you can|we will|we can|let me|let\'?s)\\s+',
  'gim'
);

const ARTICLES = /\b(?:a|an|the)\s+(?=[a-z])/gi;

// Upper bound on sentinel-restore passes. Patterns can nest (e.g. the path
// rule swallows `STARTER/BUSINESS`, then the function-call rule swallows the
// resulting `type ( 0 )`), so a single pass leaves the inner sentinel intact.
// Pass count grows with nesting depth, never with input size — 8 is far past
// any real-world depth and bounds pathological input.
const MAX_RESTORE_PASSES = 8;

// Tokens we won't touch even if they sit inside prose.
const PROTECTED_PATTERNS = [
  /```[\s\S]*?```/g,                          // fenced code
  /`[^`\n]+`/g,                               // inline code
  /\bhttps?:\/\/\S+/gi,                       // URLs
  /\b[\w.-]*[\/\\][\w.\/\\\-]+/g,             // paths with / or \
  /\b[A-Z][A-Za-z0-9]*(?:_[A-Z][A-Za-z0-9]*)+\b/g, // CONST_CASE
  /\b\w+\.\w+(?:\.\w+)*\(\)?/g,               // dotted.method or pkg.fn()
  /[A-Za-z_][A-Za-z0-9_]*\s*\([^)]*\)/g,      // function calls
  /\b\d+\.\d+\.\d+\b/g,                       // version numbers
];

function withProtectedSegments(text, transform) {
  // Replace every protected match with a sentinel, transform the rest, then
  // splice the originals back in.
  const segments = [];
  let working = text;
  for (const re of PROTECTED_PATTERNS) {
    working = working.replace(re, m => {
      const i = segments.length;
      segments.push(m);
      return `�${i}�`;
    });
  }
  let out = transform(working);
  // Restore iteratively: a single pass leaves inner sentinels unresolved when
  // patterns nested at protect time (#444).
  const sentinel = /�(\d+)�/g;
  for (let pass = 0; pass < MAX_RESTORE_PASSES; pass++) {
    sentinel.lastIndex = 0;
    if (!sentinel.test(out)) break;
    out = out.replace(/�(\d+)�/g, (_, i) => segments[+i]);
  }
  return out;
}

function compressProse(text) {
  let s = text;
  s = s.replace(LEADERS, '');
  s = s.replace(PLEASANTRIES, '');
  s = s.replace(HEDGES, '');
  s = s.replace(FILLERS, '');
  s = s.replace(ARTICLES, '');
  // Collapse repeated whitespace introduced by removals.
  s = s.replace(/[ \t]{2,}/g, ' ');
  s = s.replace(/\s+([,.;:!?])/g, '$1');
  s = s.replace(/\n{3,}/g, '\n\n');
  // Capitalize the first letter of each sentence we may have left lowercase.
  s = s.replace(/(^|[.!?]\s+)([a-z])/g, (_, pre, ch) => pre + ch.toUpperCase());
  return s.trim();
}

function compress(text, _opts) {
  if (typeof text !== 'string' || text.length === 0) {
    return { compressed: text, before: 0, after: 0 };
  }
  const before = text.length;
  const compressed = withProtectedSegments(text, compressProse);
  return { compressed, before, after: compressed.length };
}

// Walk a JSON-RPC payload and compress every `description` field in place.
// Used by the proxy on tools/list, prompts/list, resources/list responses.
function compressDescriptionsInPlace(obj, fieldNames) {
  const fields = new Set(fieldNames || ['description']);
  if (!obj || typeof obj !== 'object') return;
  if (Array.isArray(obj)) {
    for (const item of obj) compressDescriptionsInPlace(item, [...fields]);
    return;
  }
  for (const [key, val] of Object.entries(obj)) {
    if (fields.has(key) && typeof val === 'string') {
      obj[key] = compress(val).compressed;
    } else if (val && typeof val === 'object') {
      compressDescriptionsInPlace(val, [...fields]);
    }
  }
}

module.exports = { compress, compressDescriptionsInPlace, withProtectedSegments };

#!/usr/bin/env node
// caveman-shrink — MCP middleware that proxies an upstream MCP server and
// compresses prose fields so the model sees fewer tokens.
//
// Usage:
//   caveman-shrink <upstream-command> [...args]
//
// Example wrapping the filesystem MCP server:
//   "mcpServers": {
//     "fs-shrunk": {
//       "command": "npx",
//       "args": ["caveman-shrink", "npx", "@modelcontextprotocol/server-filesystem", "/some/path"]
//     }
//   }
//
// Compression is applied to:
//   - "description" fields in tools/list, prompts/list, resources/list responses
//   - same boundaries as caveman-compress: code, URLs, paths, identifiers preserved
//
// What we deliberately DON'T touch in v1:
//   - tools/call response content (high risk of breaking downstream parsing)
//   - request payloads going TO the upstream server
//
// Configuration (env vars):
//   CAVEMAN_SHRINK_FIELDS   comma-separated extra field names to compress
//                           (default: description)
//   CAVEMAN_SHRINK_DEBUG=1  log compression deltas to stderr

const { spawn } = require('child_process');
const { constants: osConstants } = require('os');
const { StringDecoder } = require('string_decoder');
const { compressDescriptionsInPlace, compress } = require('./compress');

const args = process.argv.slice(2);
if (args.length === 0) {
  process.stderr.write('caveman-shrink: missing upstream command.\n');
  process.stderr.write('Usage: caveman-shrink <upstream-command> [...args]\n');
  process.exit(2);
}

const debug = process.env.CAVEMAN_SHRINK_DEBUG === '1';
const fields = (process.env.CAVEMAN_SHRINK_FIELDS || 'description')
  .split(',').map(s => s.trim()).filter(Boolean);

const { getSpawnInvocation, getSpawnOptions } = require('./spawn-options');

let invocation;
try {
  invocation = getSpawnInvocation(args[0], args.slice(1));
} catch (error) {
  process.stderr.write(`caveman-shrink: failed to resolve upstream safely: ${error.message}\n`);
  process.exit(1);
}
const upstream = spawn(invocation.command, invocation.args, getSpawnOptions());

let spawnFailed = false;
upstream.on('error', err => {
  spawnFailed = true;
  process.stderr.write(`caveman-shrink: failed to spawn upstream: ${err.message}\n`);
});

// `exit` can fire while stdout still has unread data and while our own stdout
// is backpressured. Wait for child `close`, stop accepting client input, then
// let Node exit naturally so every transformed byte drains.
upstream.on('close', (code, signal) => {
  process.stdin.pause();
  process.stdin.removeListener('data', forwardInput);
  process.stdin.removeListener('end', endInput);
  if (spawnFailed) {
    process.exitCode = 1;
  } else if (signal) {
    process.exitCode = 128 + (osConstants.signals[signal] || 1);
  } else {
    process.exitCode = code || 0;
  }
});

// JSON-RPC framing over stdio: messages are separated by newlines (the
// MCP stdio transport uses LSP-like content but most servers emit one JSON
// object per line). We line-buffer in both directions and parse opportunistically.
function makeLineBuffer(onLine) {
  let buf = '';
  const decoder = new StringDecoder('utf8');
  const flushLines = () => {
    let nl;
    while ((nl = buf.indexOf('\n')) !== -1) {
      const line = buf.slice(0, nl);
      buf = buf.slice(nl + 1);
      if (line.trim()) onLine(line);
    }
  };
  return {
    push(chunk) {
      buf += decoder.write(chunk);
      flushLines();
    },
    end() {
      buf += decoder.end();
      if (buf.trim()) onLine(buf);
      buf = '';
    },
  };
}

function transformResponse(msg) {
  // Compress description fields on list-style responses. Match by method
  // shape — we don't always know the original request's method, so we
  // detect by the presence of a tools/prompts/resources array.
  if (!msg || !msg.result || typeof msg.result !== 'object') return msg;
  const r = msg.result;
  let compressedSomething = false;

  for (const arrayName of ['tools', 'prompts', 'resources', 'resourceTemplates']) {
    if (Array.isArray(r[arrayName])) {
      for (const item of r[arrayName]) {
        for (const field of fields) {
          if (typeof item[field] === 'string') {
            const before = item[field];
            const out = compress(before).compressed;
            if (out !== before) {
              item[field] = out;
              compressedSomething = true;
              if (debug) {
                process.stderr.write(
                  `[caveman-shrink] ${arrayName}.${item.name || '?'}.${field}: ` +
                  `${before.length}→${out.length} bytes\n`
                );
              }
            }
          }
        }
      }
    }
  }

  // Walk nested inputSchema descriptions (e.g. tool parameter descriptions).
  // Always run — top-level compression does not cover nested schemas.
  for (const arrayName of ['tools', 'prompts', 'resources', 'resourceTemplates']) {
    if (Array.isArray(r[arrayName])) {
      for (const item of r[arrayName]) {
        if (item.inputSchema) compressDescriptionsInPlace(item.inputSchema, fields);
      }
    }
  }

  return msg;
}

function writeClient(value) {
  if (process.stdout.write(value)) return;
  upstream.stdout.pause();
  process.stdout.once('drain', () => upstream.stdout.resume());
}

// Upstream → us → client (model). Transform here.
const responses = makeLineBuffer(line => {
  let msg;
  try { msg = JSON.parse(line); } catch {
    // Pass through unparseable lines unchanged.
    writeClient(line + '\n');
    return;
  }
  const out = transformResponse(msg);
  writeClient(JSON.stringify(out) + '\n');
});
upstream.stdout.on('data', chunk => responses.push(chunk));
upstream.stdout.on('end', () => responses.end());

// Client → us → upstream. Pass through unchanged for v1.
function forwardInput(chunk) {
  if (!upstream.stdin.writable || upstream.stdin.destroyed) return;
  if (!upstream.stdin.write(chunk)) {
    process.stdin.pause();
    upstream.stdin.once('drain', () => process.stdin.resume());
  }
}
function endInput() {
  if (upstream.stdin.writable && !upstream.stdin.destroyed) upstream.stdin.end();
}
upstream.stdin.on('error', err => {
  if (err.code !== 'EPIPE' && !spawnFailed) {
    process.stderr.write(`caveman-shrink: upstream stdin failed: ${err.message}\n`);
    process.exitCode = 1;
  }
});
process.stdin.on('data', forwardInput);
process.stdin.on('end', endInput);

// Spawn options for the upstream MCP child process.
//
// Windows npm tools arrive as .cmd shims. Resolve through PATH/PATHEXT and
// launch their Node target directly; never join upstream arguments into a
// cmd.exe string.
//
// Exported standalone so the behavior is unit-testable without re-running
// the CLI entry point (index.js exits immediately when args are empty).

'use strict';

const fs = require('fs');
const path = require('path');

function envValue(env, name) {
  const key = Object.keys(env).find(candidate => candidate.toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : env[key];
}

function resolveWindowsCommand(command, env) {
  if (path.isAbsolute(command) || /[\\/]/.test(command)) {
    return fs.existsSync(command) ? command : null;
  }
  const pathExt = envValue(env, 'PATHEXT') || '.COM;.EXE;.BAT;.CMD';
  // Extensionless commands resolve only through PATHEXT, matching Windows
  // semantics; the bare name next to a .CMD shim is a non-executable Unix shim.
  const names = path.extname(command)
    ? [command]
    : pathExt.split(';').map(extension =>
      `${command}${extension.startsWith('.') ? extension : `.${extension}`}`);
  for (const directory of (envValue(env, 'PATH') || '').split(';')) {
    if (!directory) continue;
    for (const name of names) {
      const candidate = path.join(directory, name);
      if (fs.existsSync(candidate)) return candidate;
    }
  }
  return null;
}

function parseWindowsNodeShim(source) {
  for (const line of source.split(/\r?\n/)) {
    if (!/(?:\bnode(?:\.exe)?\b|_prog)/i.test(line) || !/%\*/.test(line)) continue;
    // Shim-relative target (npm cmd-shim, pnpm/yarn-classic @zkochan forms), or
    // a drive-absolute target (pnpm emits one when the global bin dir and the
    // store sit on different drives — path.relative crosses drives as absolute).
    const match = line.match(/"%(?:dp0%|~dp0)\\([^"\r\n]+\.(?:cjs|mjs|js))"\s+%\*/i)
      || line.match(/"([A-Za-z]:[\\/][^"\r\n]+\.(?:cjs|mjs|js))"\s+%\*/i);
    if (match) return match[1];
  }
  return null;
}

function getSpawnInvocation(command, args, platform = process.platform, env = process.env) {
  if (platform !== 'win32') return { command, args: [...args] };
  const executable = resolveWindowsCommand(command, env) || command;
  if (!/\.(?:cmd|bat)$/i.test(executable)) return { command: executable, args: [...args] };
  const stat = fs.statSync(executable);
  if (!stat.isFile() || stat.size > 256 * 1024) {
    throw new Error(`cannot safely launch Windows command shim: ${executable}`);
  }
  const relativeScript = parseWindowsNodeShim(fs.readFileSync(executable, 'utf8'));
  if (!relativeScript) throw new Error(`cannot safely launch non-Node Windows command shim: ${executable}`);
  const script = /^[A-Za-z]:[\\/]/.test(relativeScript)
    ? relativeScript
    : path.resolve(path.dirname(executable), ...relativeScript.split(/[\\/]+/));
  if (!fs.statSync(script).isFile()) throw new Error(`Windows command shim target is missing: ${script}`);
  return { command: process.execPath, args: [script, ...args] };
}

function getSpawnOptions(platform = process.platform) {
  return {
    stdio: ['pipe', 'pipe', 'inherit'],
    windowsHide: true,
  };
}

module.exports = { getSpawnInvocation, getSpawnOptions, parseWindowsNodeShim, resolveWindowsCommand };
